#include "Companies/FoundrylineBusinessLedger.h"
#include "Companies/FoundrylinePropertyLot.h"

void FFoundrylineBusinessLedger::Seed(){
 State={};FFoundrylineBusinessCompany C;C.Id=StarterCompany();C.PlantId=StarterPlant();C.PlotId=FGuid(0xF001,3,1,1);C.Name=TEXT("Foundryline Co-op");State.Companies.Add(C);
 const int Offsets[]={0,12000,-12000,24000};for(int I=0;I<4;++I){auto R=FFoundrylinePropertyLot::Starter(C.Id,C.PlantId).Region;const FIntVector Offset(Offsets[I],0,0);FFoundrylineBusinessPlot P;P.Id=I?FGuid(0xF001,30,uint32(I+1),1):C.PlotId;P.Bounds.Min=R.Bounds.Min+Offset;P.Bounds.Max=R.Bounds.Max+Offset;P.BuildingBounds.Min=R.BuildingBounds.Min+Offset;P.BuildingBounds.Max=R.BuildingBounds.Max+Offset;if(!I)P.Company=C.Id;State.Plots.Add(P);}
}
FGuid FFoundrylineBusinessLedger::CompanyFor(const FString& A)const{const auto* M=State.Members.FindByPredicate([&](const auto& V){return V.Account==A;});return M?M->Company:FGuid();}
const FFoundrylineBusinessCompany* FFoundrylineBusinessLedger::Company(FGuid Id)const{return State.Companies.FindByPredicate([&](const auto& C){return C.Id==Id;});}
bool FFoundrylineBusinessLedger::EnrolCoop(const FString& A,FString& E){if(A.IsEmpty()||A.Len()>256){E=TEXT("Invalid account");return false;}if(State.Members.ContainsByPredicate([&](const auto& M){return M.Account==A;})){if(CompanyFor(A).IsValid())return true;E=TEXT("An invitation is required to rejoin");return false;}if(State.Members.Num()>=128){E=TEXT("Membership limit");return false;}auto* C=State.Companies.FindByPredicate([](const auto& V){return V.Id==StarterCompany();});if(!C){E=TEXT("Co-op unavailable");return false;}if(C->OwnerAccount.IsEmpty())C->OwnerAccount=A;State.Members.Add({A,C->Id});return true;}
bool FFoundrylineBusinessLedger::Create(const FString& A,const FString& Name,FGuid PlotId,FString& E){
 const FString N=Name.TrimStartAndEnd();auto* P=State.Plots.FindByPredicate([&](const auto& V){return V.Id==PlotId;});const auto* Old=Company(CompanyFor(A));
 if(A.IsEmpty()||A.Len()>256||N.IsEmpty()||N.Len()>64||!P||P->Company.IsValid()||State.Companies.Num()>=16||State.Members.Num()>=128&&!State.Members.ContainsByPredicate([&](const auto& V){return V.Account==A;})||Old&&Old->OwnerAccount==A){E=TEXT("Choose a free plot; an owner must retain their existing business");return false;}
 FFoundrylineBusinessCompany C;C.Id=FGuid::NewGuid();C.PlantId=FGuid::NewGuid();C.PlotId=P->Id;C.Name=N;C.OwnerAccount=A;P->Company=C.Id;State.Companies.Add(C);State.Members.RemoveAll([&](const auto& M){return M.Account==A;});State.Members.Add({A,C.Id});State.Invitations.RemoveAll([&](const auto& I){return I.Account==A;});return true;
}
bool FFoundrylineBusinessLedger::Invite(const FString& Owner,const FString& A,FString& E){const auto* C=Company(CompanyFor(Owner));const auto* Other=Company(CompanyFor(A));if(!C||C->OwnerAccount!=Owner||A.IsEmpty()||A.Len()>256||A==Owner||Other&&(Other->OwnerAccount==A||Other->Id==C->Id)||State.Invitations.Num()>=256){E=TEXT("Only a company owner can invite a non-owner");return false;}if(!State.Invitations.ContainsByPredicate([&](const auto& I){return I.Account==A&&I.Company==C->Id;}))State.Invitations.Add({A,C->Id});return true;}
bool FFoundrylineBusinessLedger::Accept(const FString& A,FGuid Id,FString& E){const auto* Old=Company(CompanyFor(A));if(State.Members.Num()>=128&&!State.Members.ContainsByPredicate([&](const auto& V){return V.Account==A;})||!Company(Id)||Old&&Old->OwnerAccount==A||!State.Invitations.ContainsByPredicate([&](const auto& I){return I.Account==A&&I.Company==Id;})){E=TEXT("An invitation is required; owners cannot abandon their company");return false;}State.Members.RemoveAll([&](const auto& M){return M.Account==A;});State.Members.Add({A,Id});State.Invitations.RemoveAll([&](const auto& I){return I.Account==A;});return true;}
bool FFoundrylineBusinessLedger::RemoveMember(const FString& Owner,const FString& A,FString& E){const auto* C=Company(CompanyFor(Owner));if(!C||C->OwnerAccount!=Owner||Owner==A||CompanyFor(A)!=C->Id){E=TEXT("Only an owner can remove another member of their company");return false;}for(auto& M:State.Members)if(M.Account==A)M.Company.Invalidate();State.Invitations.RemoveAll([&](const auto& I){return I.Account==A&&I.Company==C->Id;});return true;}
bool FFoundrylineBusinessLedger::AdjustBalance(FGuid Id,int64 Delta,FString& E){auto* C=State.Companies.FindByPredicate([&](const auto& V){return V.Id==Id;});if(!C||Delta<0&&(Delta==MIN_int64||C->BalanceCents< -Delta)||Delta>0&&C->BalanceCents>MAX_int64-Delta){E=TEXT("Insufficient funds or balance overflow");return false;}C->BalanceCents+=Delta;return true;}
FFoundrylineBuildRegion FFoundrylineBusinessLedger::Region(FGuid Id)const{FFoundrylineBuildRegion R;const auto* P=State.Plots.FindByPredicate([&](const auto& V){return V.Id==Id;});if(!P)return R;const auto* C=Company(P->Company);if(!C)return R;R.RegionId=P->Id;R.CompanyId=C->Id;R.PlantId=C->PlantId;R.SurfaceId=TEXT("StarterLand");R.Bounds=P->Bounds;R.BuildingBounds=P->BuildingBounds;R.bHasBuildingSetback=true;return R;}
bool FFoundrylineBusinessLedger::Valid(FString& E)const{
 auto Fail=[&](){E=TEXT("Invalid business ownership snapshot");return false;};if(State.Version!=1||State.Companies.Num()<1||State.Companies.Num()>16||State.Plots.Num()!=4||State.Members.Num()>128||State.Invitations.Num()>256)return Fail();TSet<FGuid> Cs,Ps,Ls;TSet<FString> Accounts;
 FFoundrylineBusinessLedger Authored;Authored.Seed();for(const auto& P:State.Plots){const auto* Expected=Authored.State.Plots.FindByPredicate([&](const auto& V){return V.Id==P.Id;});if(!Expected||Ls.Contains(P.Id)||P.Bounds.Min!=Expected->Bounds.Min||P.Bounds.Max!=Expected->Bounds.Max||P.BuildingBounds.Min!=Expected->BuildingBounds.Min||P.BuildingBounds.Max!=Expected->BuildingBounds.Max)return Fail();Ls.Add(P.Id);}
 for(const auto& C:State.Companies){if(!C.Id.IsValid()||!C.PlantId.IsValid()||Cs.Contains(C.Id)||Ps.Contains(C.PlantId)||C.Name.TrimStartAndEnd().IsEmpty()||C.Name.Len()>64||C.BalanceCents<0||C.OwnerAccount.Len()>256)return Fail();Cs.Add(C.Id);Ps.Add(C.PlantId);const auto* P=State.Plots.FindByPredicate([&](const auto& V){return V.Id==C.PlotId;});if(!P||P->Company!=C.Id||C.OwnerAccount.IsEmpty()&&(C.Id!=StarterCompany()||!State.Members.IsEmpty()))return Fail();}
 if(!Cs.Contains(StarterCompany())||!Company(StarterCompany())||Company(StarterCompany())->PlantId!=StarterPlant()||Company(StarterCompany())->PlotId!=FGuid(0xF001,3,1,1))return Fail();
 for(const auto& M:State.Members){if(M.Account.IsEmpty()||M.Account.Len()>256||Accounts.Contains(M.Account)||M.Company.IsValid()&&!Cs.Contains(M.Company))return Fail();Accounts.Add(M.Account);}
 for(const auto& C:State.Companies)if(!C.OwnerAccount.IsEmpty()&&CompanyFor(C.OwnerAccount)!=C.Id)return Fail();for(const auto& P:State.Plots)if(P.Company.IsValid()&&(!Cs.Contains(P.Company)||Company(P.Company)->PlotId!=P.Id))return Fail();
 TSet<FString> Invites;for(const auto& I:State.Invitations){const FString Key=I.Account+I.Company.ToString();if(I.Account.IsEmpty()||I.Account.Len()>256||!Cs.Contains(I.Company)||Invites.Contains(Key))return Fail();Invites.Add(Key);}return true;
}
bool FFoundrylineBusinessLedger::Restore(const FFoundrylineBusinessState& S,FString& E){FFoundrylineBusinessLedger Copy;Copy.State=S;if(!Copy.Valid(E))return false;State=S;return true;}
